n=30
g=[[0]*n for _ in range(n)]
rs=[1,8,16,23]; cs=[1,8,15,22]
tiles=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ti,r0 in enumerate(rs):
 for tj,c0 in enumerate(cs):
  for r in range(r0,r0+5):
   for c in range(c0,c0+5):
    g[r][c]= tiles[ti][tj] if r0+1<=r<=r0+3 and c0+1<=c<=c0+3 else 4
# clipped partial fifth column tile borders
for r0 in rs:
 for r in range(r0,r0+5): g[r][29]=4
# draw connectors by color between corner tiles, only on currently blank cells
def horizontal(color, tile_row, cstart, cend):
 r0=rs[tile_row]
 for r in range(r0+1,r0+4):
  for c in range(cs[cstart]+1,cs[cend]+4):
   if g[r][c]==0: g[r][c]=color
def vertical(color,tile_col,rstart,rend):
 c0=cs[tile_col]
 for c in range(c0+1,c0+4):
  for r in range(rs[rstart]+1,rs[rend]+4):
   if g[r][c]==0: g[r][c]=color
# color 3 rectangle at tile corners (rows 0,2; cols 0,3)
for tr in [0,2]: horizontal(3,tr,0,3)
for tc in [0,3]: vertical(3,tc,0,2)
# color 8 rectangle (rows 1,3; cols 1,2)
for tr in [1,3]: horizontal(8,tr,1,2)
for tc in [1,2]: vertical(8,tc,1,3)
print(len(g),set(map(len,g)))
print('\n'.join(' '.join(map(str,row)) for row in g))

h=[row[:] for row in [[0]*30 for _ in range(30)]]
# recreate input grid
for ti,r0 in enumerate(rs):
 for tj,c0 in enumerate(cs):
  for r in range(r0,r0+5):
   for c in range(c0,c0+5): h[r][c]=tiles[ti][tj] if r0+1<=r<=r0+3 and c0+1<=c<=c0+3 else 4
for r0 in rs:
 for r in range(r0,r0+5): h[r][29]=4
# one-cell centerline connectors
def hline(colr,tr,cstart,cend):
 rr=rs[tr]+2
 for cc in range(cs[cstart]+2,cs[cend]+3):
  if h[rr][cc]==0: h[rr][cc]=colr
def vline(colr,tc,rstart,rend):
 cc=cs[tc]+2
 for rr in range(rs[rstart]+2,rs[rend]+3):
  if h[rr][cc]==0: h[rr][cc]=colr
for tr in [0,2]: hline(3,tr,0,3)
for tc in [0,3]: vline(3,tc,0,2)
for tr in [1,3]: hline(8,tr,1,2)
for tc in [1,2]: vline(8,tc,1,3)
print(json.dumps({'action':'submit','grid':h},separators=(',',':')))

k=[row[:] for row in g] # g is first solution already lines 3/8
# add color2 lines according to its repeated rectangular arrangements
for tr,cstart,cend in [(0,1,2),(2,1,2),(1,0,3),(3,0,3)]:
 r0=rs[tr]
 for r in range(r0+1,r0+4):
  for c in range(cs[cstart]+1,cs[cend]+4):
   if k[r][c]==0: k[r][c]=2
for tc,rstart,rend in [(0,1,3),(3,1,3),(1,0,2),(2,0,2)]:
 c0=cs[tc]
 for c in range(c0+1,c0+4):
  for r in range(rs[rstart]+1,rs[rend]+4):
   if k[r][c]==0: k[r][c]=2
print(json.dumps({'action':'submit','grid':k},separators=(',',':')))

m=[row[:] for row in h] # centerline 3/8
for tr,cstart,cend in [(0,1,2),(2,1,2),(1,0,3),(3,0,3)]:
 rr=rs[tr]+2
 for cc in range(cs[cstart]+2,cs[cend]+3):
  if m[rr][cc]==0: m[rr][cc]=2
for tc,rstart,rend in [(0,1,3),(3,1,3),(1,0,2),(2,0,2)]:
 cc=cs[tc]+2
 for rr in range(rs[rstart]+2,rs[rend]+3):
  if m[rr][cc]==0: m[rr][cc]=2
print(json.dumps({'action':'submit','grid':m},separators=(',',':')))

